export type MarkName = keyof typeof MARKS;

export const MARK_NAMES = Object.keys(MARKS) as [MarkName, ...MarkName[]];

const bySkill = new Map<string, MarkName>(
  (Object.entries(MARKS) as [MarkName, Mark][]).flatMap(([name, mark]) =>
    (mark.skills ?? []).map((skill) => [skill.toLowerCase(), name] as const),
  ),
);

/** The mark for a skill tag, matched without regard to case. */
export function skillMark(skill: string): MarkName | undefined {
  return bySkill.get(skill.toLowerCase());
}

/** The mark itself when it is a symbol, small enough to sit in a line of text; wordmarks give undefined. */
export function symbolMark(name: MarkName | undefined): MarkName | undefined {
  return name && MARKS[name].shape === "symbol" ? name : undefined;
}
